#!/usr/bin/env python3
"""Record verification evidence without changing native CAD."""
import json,hashlib,re
from pathlib import Path
from check_schematic_contracts import check
R=Path(__file__).resolve().parents[1]
def sha(p):return hashlib.sha256((R/p).read_bytes()).hexdigest()
contract=json.loads((R/'docs/design/power_contract.json').read_text())
facts={p['mpn']:p for p in json.loads((R/'docs/components/power_facts.json').read_text())}
syms={}
for file in ['.build/power_discover_results.jsonl','.build/power_scratch_results.jsonl','.build/power_scratch_fix_results.jsonl']:
 for line in (R/file).read_text().splitlines():
  r=json.loads(line)
  if r['tool']=='get_symbol_info':
   d=r['result'][0];syms[d['lib_id']]=d
pinquery=json.loads((R/'.build/power_pin_locations.json').read_text())
libmap={'U101':'Tinkerbadge_Power:TPS2121RUXR','U102':'Battery_Management:BQ24074RGT','U103':'Tinkerbadge_Power:TPS63802DLAR','U104':'Tinkerbadge_Power:TPS22918DBVR','U105':'Power_Protection:TPD4E05U06DQA','U106':'Regulator_Linear:TLV75733PDRV','U107':'Tinkerbadge_Power:TMUX1511PWR','J101':'Connector:USB_C_Receptacle_USB2.0_16P','Q101':'Transistor_FET:AO3400A'}
maprecords=[]
for ref,lib in libmap.items():
 if not any(c['ref']==ref for c in contract['components']):continue
 c=next(c for c in contract['components'] if c['ref']==ref);s=syms[lib];by={p['number']:p for p in s['pins']}
 assert set(c['pins'])==set(by),(ref,set(c['pins'])^set(by))
 rows=[]
 manufacturer=facts.get(c['mpn'],{})
 for p in manufacturer.get('pins',[{'number':str(n),'name':name} for n,name in [(1,'G'),(2,'S'),(3,'D')]]):
  num=c.get('physical_pin_aliases',{}).get(p['number'],p['number']);row={'physical_lead':p['number'],'manufacturer_function':p['name'],'symbol_pin':num,'symbol_name':by[num]['name'],'symbol_type':by[num]['type'],'project_net':c['pins'][num]};rows.append(row)
 maprecords.append({'reference_example':ref,'mpn':c['mpn'],'symbol':lib,'source':manufacturer.get('source','docs/datasheets/AO3400A.pdf'),'source_pages':manufacturer.get('critical_pages',[1]),'symbol_pin_count':len(by),'physical_rows':len(rows),'footprint_assignment':None,'footprint_acceptance':'Pending; no manufacturing footprint is assigned in the electrical development capture.','rows':rows})
(R/'docs/design/power_symbol_map.json').write_text(json.dumps(maprecords,indent=2,ensure_ascii=False)+'\n')
lines=['# Power symbol capture map','','Electrical symbol mapping is accepted against the source review in [review_power.md](review_power.md). This is not a complete symbol-to-PCB pad acceptance record. Instance footprints are blank; pad geometry, paste and assembly orientation remain blocked before PCB use.','','Custom symbols were created only through Konnect in `power_symbols.kicad_sym`, registered as `Tinkerbadge_Power`, queried back and placed in a disposable project. The rendered inspection is `.build/power_symbolcheck/symbols_final.png`. Every queried electrical pin number matches the source contract. The converter symbol was adjusted after its first render to eliminate a pin-name collision.','','The machine-readable rows are in `power_symbol_map.json`. AO3400A numbering is explicitly project-assigned from the manufacturer’s indexed G/S/D physical view. USB shell aliases preserve four separate physical anchors under one SH electrical pin.','']
for m in maprecords:
 lines += [f"## {m['mpn']} ({m['reference_example']})",'',f"Symbol: `{m['symbol']}`. Source: `{m['source']}`, pages {', '.join(map(str,m['source_pages']))}.",'','| Physical lead | Manufacturer function | Symbol pin / name / type | Net |','|---|---|---|---|']
 lines += [f"| {x['physical_lead']} | {x['manufacturer_function']} | {x['symbol_pin']} / {x['symbol_name']} / {x['symbol_type']} | {x['project_net'] if x['project_net'] is not None else 'NC'} |" for x in m['rows']]
 lines += ['']
lines += ['## Remaining interfaces and discrete parts','','D101/D102 use `Device:D_Zener`: symbol pin 1 is K and pin 2 is A, matching the explicitly project-numbered SMF6.0A cathode/anode map. Their final 270° symbol rotation puts K above A; both exported nets were rechecked after rotation. J102/J103/J104 use the two-terminal logical connector symbol, with unassigned physical parts and footprints. J104 is marked `NTC (DNP)` and carries `Populate=DNP`. The installed MCP has no native DNP-attribute operation, so downstream assembly/BOM tooling must honor the contract’s fitted=false entry and not infer population from a missing native flag.','','Standard footprint queries are retained under `.build/power_footprint_query_*.json`. They informed orientation checks, not blanket acceptance. In particular, the BQ symbol’s default EP1.6 footprint was not accepted in place of the saved RGT0016C drawing’s EP1.68 dimensions; the instance footprint is blank. AOS recommended land geometry differs from the standard SOT-23 candidate and remains a physical review gate.']
(R/'docs/design/power_symbol_map.md').write_text('\n'.join(lines)+'\n')
result=check(R/'.build/power.net',['power']);assert result['status']=='PASS'
checks={}
for name in ['validate_component_connections','validate_wire_connections','find_shorted_nets','find_orphan_items']:
 d=json.loads((R/'.build'/('power_'+name+'.json')).read_text());assert not d['isError'];checks[name]=d['result'][0]
erc=json.loads((R/'.build/power_root_erc.json').read_text());powererc=[v for v in erc if any(re.search(r'\b[UQJDRCL]1[0-9]{2}\b',i.get('description','')) for i in v.get('items',[]))]
capture_review=json.loads((R/'docs/design/power_capture_review.json').read_text())
review_hashes=capture_review.get('hashes',{})
review_matches=(review_hashes.get('power.kicad_sch')==sha('power.kicad_sch') and review_hashes.get('docs/design/power_contract.json')==sha('docs/design/power_contract.json') and capture_review.get('status','').startswith('PASS'))
review_status='PASS independent electrical, properties and visual capture; matching sheet and contract hashes' if review_matches else 'Pending separate reviewer signoff for the current sheet and contract'
record={'date':'2026-11-09','scope':'Power electrical development capture only','kicad_version':'10.0.8','contract_sha256':sha('docs/design/power_contract.json'),'schematic_sha256':sha('power.kicad_sch'),'symbol_library_sha256':sha('power_symbols.kicad_sym'),'netlist_sha256':sha('.build/power.net'),'contract_comparison':result,'konnect_checks':checks,'root_erc_snapshot':{'file':'.build/power_root_erc.json','findings_naming_power_references':len(powererc),'whole_project_findings':len(erc),'whole_project_errors':sum(v.get('severity')=='error' for v in erc),'whole_project_warnings':sum(v.get('severity')=='warning' for v in erc),'whole_project_status':'Completed root ERC; inspect and justify every recorded finding. Footprint/prototype gates remain.'},'visual_preview':'.build/power_final_reviewed.png','source_review':'docs/design/review_power.md','independent_capture_review':review_status,'property_comparison':json.loads((R/'.build/power_single_3v3_properties.json').read_text()),'root_contract_comparison':json.loads((R/'.build/power_single_3v3_root_contracts.json').read_text()),'safety_state':{'charging':'Hard disabled by fitted R120 from VSYS to CE','battery':'Logical two-wire protected 1S 4.2 V LiPo interface; exact pack/connector/polarity pending','thermistor':'Separate J104 is unpopulated; fitting it alone does not enable or qualify charging','rail':'One nominal 3.3 V rail; calculated 3.2559–3.3443 V static PWM bounds. Below-3.3 V LED behavior is an accepted prototype exception, not guaranteed.','footprints':'All power-instance footprints are blank pending physical acceptance'}}
(R/'docs/design/power_verification.json').write_text(json.dumps(record,indent=2,ensure_ascii=False)+'\n')
lines=['# Power capture verification','','9 November 2026. KiCad 10.0.8. Electrical development capture only.','','- Source and assignment review: [review_power.md](review_power.md), including the two-wire, USB shell and [single-3.3 V amendment](review_power_single_3v3.md).',f"- Independent exported-netlist checker: PASS, {result['expected_components']} components, {result['expected_endpoints']} endpoints, {result['intentional_nc_endpoints']} intentional NC endpoints, no missing or extra endpoints.",'- Konnect checks: zero unconnected pins, zero floating wire endpoints, zero merged named nets and zero orphan items.',f"- Root ERC snapshot: errors={sum(v.get('severity')=='error' for v in erc)}, warnings={sum(v.get('severity')=='warning' for v in erc)}; findings naming power references={len(powererc)}. The current warning is the intentional U502 SDO/SA0 I2C address strap to +3V3; review its original-source justification in the peripheral records. No ERC result establishes prototype or manufacturing readiness.",f'- Independent capture status: {review_status}.','- Disposable symbols were queried and rendered, then actual sheet pins were queried. The final render was inspected and field/ground-stub collisions corrected. See the matching-hash [independent capture review](power_capture_review.md).','','## Pinned evidence','',f"- Contract: `{record['contract_sha256']}`",f"- Power sheet: `{record['schematic_sha256']}`",f"- Power symbol library: `{record['symbol_library_sha256']}`",f"- Exported power netlist: `{record['netlist_sha256']}`",'','Machine-readable results: [power_verification.json](power_verification.json). Preview: `.build/power_final_reviewed.png`. Native writes were performed only by Konnect; orchestration/results are under `tools/` and `.build/`. Successful mutation stages are not idempotent and must not be rerun blindly.','','## Build and release gates','','Charging is hard-disabled in hardware by fitted R120. J104 remains DNP; fitting a thermistor does not enable or qualify charging. J102 is a logical two-wire interface, not a vendor connector pinout. All power footprints are deliberately unassigned. The accepted single-3.3 V LED prototype exception, exact stock pack, connector polarity/current rating, autonomous temperature qualification, inductor and capacitor MPNs, startup/current-mode transitions, rail/transient limits, ADC brownout behavior, storage draw and thermal performance still require selection or testing. No board layout, manufacturing or production readiness is established.']
(R/'docs/design/power_verification.md').write_text('\n'.join(lines)+'\n')
print(json.dumps({'contract':record['contract_sha256'],'sheet':record['schematic_sha256'],'netlist':record['netlist_sha256'],'status':result['status'],'root_erc_power_findings':len(powererc)},indent=2))
